input.newString:
  it('excludes non-Permanent Ability RollBonus from the total, surfacing it as conditional instead', () => {
    const sheet = makeSheet({ AbilityIds: ['ab-martyr'] });
    const b = computeRollBreakdown(sheet, 'v-mettle', library);
    expect(b.Total).toBe(2); // base Mettle only
    const conditional = conditionalRollBonuses(sheet, library, 'v-mettle');
    expect(conditional.length).toBeGreaterThan(0);
  });

  it('does not count Neutral Status as hindering — only Negative Statuses hinder', () => {
    const sheet = makeSheet({
      Statuses: [
        makeStatus({ Id: 'st-a', Name: 'Watched', Rank: 5, Polarity: 'Neutral' }),
        makeStatus({ Id: 'st-b', Name: 'Rattled', Rank: 3, Polarity: 'Negative' }),
        makeStatus({ Id: 'st-c', Name: 'Exposed', Rank: 1, Polarity: 'Negative' }),
      ],
    });
    const b = computeRollBreakdown(sheet, 'v-might', library);
    // base 1 - hindering 3 (Rattled, the highest Negative — Watched is Neutral and ignored)
    expect(b.Total).toBe(-2);
    const hindering = b.Sources.filter((s) => s.Label.includes('hindering'));
    expect(hindering).toHaveLength(1);
    expect(hindering[0].Label).toContain('Rattled');
  });

  it('does not count Neutral Status as hindering when no Negative Status exists', () => {
    const sheet = makeSheet({
      Statuses: [
        makeStatus({ Id: 'st-a', Name: 'Watched', Rank: 5, Polarity: 'Neutral' }),
      ],
    });
    const b = computeRollBreakdown(sheet, 'v-might', library);
    expect(b.Total).toBe(1);
    expect(b.Sources.filter((s) => s.Kind === 'Status')).toHaveLength(0);
  });
});

